library(shiny)
library(readr)
library(reactable)
library(rlang)
library(dplyr)
library(htmltools)
library(htmlwidgets)

# Globals
contaminant_shapes  <- list("Mercury"="circle","PCB"="square","PFAS"="triangle")
contaminant_colours <- list("Mercury"="#1f77b4","PCB"="#ff7f0e","PFAS"="#2ca02c")
length_levels <- c("15-20cm", "20-25cm", "25-30cm", "30-35cm", "35-40cm", "40-45cm",
                   "45-50cm", "50-55cm", "55-60cm", "60-65cm", "65-70cm", "70-75cm", ">75cm")

# Data path: prefer app-local for exported site; fallback for local dev
t1_path <- "data/t1_wide.csv"
thr_path <- "data/consumption_threshold.csv"


t1_wide <- readr::read_csv(t1_path, show_col_types = FALSE)
thr_df <- if (file.exists(thr_path)) {readr::read_csv(thr_path, show_col_types = FALSE)} else {tibble::tibble()}



# Validate data present
if (!file.exists("data/t1_wide.csv")) {
  stop("Missing data/t1_wide.csv. Ensure the data directory is included in the exported app.")
}

# After reading:
validate_cols <- c("Species","Species_display","Row_Label")
stopifnot(all(validate_cols %in% names(t1_wide)))




if (dir.exists("shared")) {
  r_files <- list.files("shared", pattern = "\\.R$", full.names = TRUE)
  lapply(r_files, source)
} else if (interactive() && dir.exists("../../R")) {
  r_files <- list.files("../../R", pattern = "\\.R$", full.names = TRUE)
  lapply(r_files, source)
}






## Example switch to URL reading (only if you’re sure files are web-served):
#t1_url  <- "./data/t1_wide.csv"
#thr_url <- "./data/consumption_threshold.csv"
#
#t1_wide <- readr::read_csv(t1_url, show_col_types = FALSE)
#thr_df  <- tryCatch(readr::read_csv(thr_url, show_col_types = FALSE),
#                    error = function(e) tibble::tibble())

#Consumption thresholds

get_threshold <- function(sp) {
  if (nrow(thr_df)) {
    v <- thr_df$threshold[match(sp, thr_df$Species)]
    ifelse(is.na(v), 8, v)
  } else 8
}


# Fallback generate_shape used by your renderer
generate_shape <- function(shape = "circle", colour = "gray", size = 12) {
  if (shape == "triangle") {
    tags$svg(width = size, height = size, viewBox = "0 0 20 20", `aria-hidden` = "true",
             tags$polygon(points = "10,3 18,17 2,17", fill = colour)
    )
  } else if (shape == "square") {
    tags$svg(width = size, height = size, viewBox = "0 0 20 20", `aria-hidden` = "true",
             tags$rect(x = 3, y = 3, width = 14, height = 14, fill = colour)
    )
  } else {
    tags$svg(width = size, height = size, viewBox = "0 0 20 20", `aria-hidden` = "true",
             tags$circle(cx = 10, cy = 10, r = 7, fill = colour)
    )
  }
}





if (!exists("render_t1_table")) {
  stop("render_t1_table() is not available. Did you include shared/*.R in the export?")
}


base_cols     <- c("Species","Species_display","Row_Label")
length_levels <- setdiff(names(t1_wide), base_cols)
species_choices <- sort(unique(t1_wide$Species))
default_species <- if ("Walleye" %in% species_choices) "Walleye" else species_choices[1]

ui <- fluidPage(
  tags$head(tags$style("main{max-width:1200px;margin:0 auto}")),
  h2("Tier 1 — Advisory Table (AOC)"),
  fluidRow(
    column(6, selectInput("species","Species",
                          choices = sort(unique(t1_wide$Species)),
                          selected = if ("Walleye" %in% t1_wide$Species) "Walleye" else sort(unique(t1_wide$Species))[1])),
    column(6, div(style="margin-top:28px;",
                  textOutput("threshold_text")))   # just display, not editable
  ),
  uiOutput("tbl")
)

server <- function(input, output) {
  filtered <- reactive({
    req(input$species)
    out <- subset(t1_wide, Species == input$species)
    req(nrow(out) > 0)
    out
  })
  
  
  output$threshold_text <- renderText({
    paste("Community desired consumption rate:", get_threshold(input$species), "meals/month")
  })
  
  output$tbl <- renderUI({
    render_t1_table(
      df = filtered(),
      length_levels = length_levels,
      contaminant_shapes = contaminant_shapes,
      contaminant_colours = contaminant_colours,
      generate_shape_fn = generate_shape,
      table_height = "1200px",
      show_legend = TRUE,
      restrict_threshold = get_threshold(input$species)
    )
  })
}


shinyApp(ui, server)

#' Generate Tier 1 Advisory Table (AOC only)
#'
#' Displays MECP advisory levels and contaminant drivers by species, size, and population type.
#' Formats include colour-coded cells and icon-based contaminant indicators.
#'
#' @param df AOC-only data from make_restrict_table()
#' @param length_levels Ordered vector of size class labels
#' @param contaminant_shapes Named list mapping contaminant to shape
#' @param contaminant_colours Named list mapping contaminant to colour
#' @param generate_shape_fn Function to draw inline shape (default = generate_shape)
#' @param restrict_threshold Numeric threshold for advisory levels to flag as restrictive
#' @param table_height CSS height for table
#' @param show_legend Logical, whether to include contaminant legend
#' @return A reactable object with legend and formatted table



render_t1_table <- function(df,
                            length_levels = NULL,
                            interest_species = NULL,
                            contaminant_shapes,
                            contaminant_colours,
                            generate_shape_fn = generate_shape,
                            table_height = "1500px",
                            show_legend = TRUE,
                            restrict_threshold = 8) {
  
  if (is.null(length_levels)) {
    length_levels <- tryCatch(get("length_levels", envir = .GlobalEnv),
                              error = function(...) intersect(names(df), names(df)))
  }
  
  
  
  size_cols <- length_levels[length_levels %in% names(df)]
  
  if (!is.null(interest_species)) {
    if (exists("filter_interest_species", mode = "function")) {
      df <- filter_interest_species(df, interest_species)
    } else {
      df <- df[df$Species %in% interest_species, , drop = FALSE]
    }
  }
  
  
  
  columns_list <- list()
  for (col_name in size_cols) {
    columns_list[[col_name]] <- colDef(
      name = col_name,
      html = TRUE,
      cell = function(value, index) {
        row <- df[index, ]
        row_type <- row$Row_Label
        
        if (row_type == "Adv cause" && !is.na(value) && nzchar(value)) {
          causes <- trimws(unlist(strsplit(value, ",")))
          icons <- lapply(causes, function(cause) {
            shape <- contaminant_shapes[[cause]] %||% "circle"
            colour <- contaminant_colours[[cause]] %||% "gray"
            generate_shape_fn(shape, colour, size = 12)
          })
          # OLD: return(htmltools::span(icons))
          return(do.call(htmltools::span, c(icons, list(style = "display:inline-flex;gap:6px;align-items:center;"))))
        
        }
        
        if (row_type != "Adv cause" && !is.na(value)) return(value)
        return("")
      },
      style = function(value, index) {
        row <- df[index, ]
        row_type <- row$Row_Label
        styles <- list(padding = "0", margin = "0", fontWeight = "bold", fontFamily = "system-ui, sans-serif")
        
        if (row_type == "Adv cause") {
          styles$paddingTop <- "0"
          styles$paddingBottom <- "10px"
        } else if (!is.na(value)) {
          val <- as.numeric(value)
          styles$background <- if (val < restrict_threshold) "#d80032" else "#4CAF50"
          styles$color <- "#ffffff"
        } else if ((is.na(value) || value == "") && row_type %in% c("General", "Sensitive")) {
          styles$background <- "#eeeeee"
          styles$color <- "#000000"
        }
        
        return(styles)
      }
    )
  }
  
  columns_list$Row_Label <- colDef(
    name = "Population",
    sticky = "left",
    minWidth = 120,
    style = function(value) {
      base <- list(fontSize = "13px", fontWeight = "bold", fontFamily = "system-ui, sans-serif")
      if (value == "Adv cause") base <- modifyList(base, list(fontSize = "10px", fontStyle = "italic"))
      return(base)
    },
    headerStyle = list(whiteSpace = "nowrap")
  )
  
  columns_list$Species <- colDef(show = FALSE)
  columns_list$Species_display <- colDef(
    name = "Species",
    sticky = "left",
    minWidth = 140,
    style = list(fontWeight = "bold", fontSize = "15px", fontFamily = "system-ui, sans-serif")
  )
  
  rowStyle_fn <- function(index) {
    row <- df[index, ]
    prev_row <- if (index > 1) df[index - 1, ] else NULL
    next_row <- if (index < nrow(df)) df[index + 1, ] else NULL
    
    style <- list()
    if (row$Row_Label %in% c("General", "Sensitive")) style$height <- "32px"
    if (is.null(prev_row) || prev_row$Species != row$Species) style$borderTop <- "2px solid #666"
    if (is.null(next_row) || next_row$Species != row$Species) style$borderBottom <- "2px solid #666"
    return(style)
  }
  
  legend_html <- if (show_legend) {
    legend_items <- lapply(names(contaminant_shapes), function(contaminant) {
      shape <- contaminant_shapes[[contaminant]]
      colour <- contaminant_colours[[contaminant]]
      htmltools::div(
        style = "display: inline-block; margin-right: 12px; font-family: sans-serif; font-size: 13px;",
        generate_shape_fn(shape, colour, 12),
        contaminant
      )
    })
    
    htmltools::div(
      style = "margin-bottom: 10px; font-family: system-ui, sans-serif; font-size: inherit; color: black;",
      htmltools::strong("Advisory Cause:"),
      htmltools::div(style = "display: flex; flex-wrap: wrap; gap: 12px;", legend_items)
    )
  } else {
    NULL
  }
  
  htmltools::div(
    htmltools::browsable(htmltools::tagList(
      legend_html,
      reactable::reactable(
        df,
        columns = columns_list,
        defaultPageSize = 10,
        showPageSizeOptions = TRUE,
        pagination = FALSE,
        sortable = FALSE,
        height = table_height,
        defaultColDef = colDef(
          sortable = FALSE,
          align = "center",
          minWidth = 80,
          style = list(
            padding = "0",
            margin = "0",
            border = "none",
            verticalAlign = "middle",
            fontFamily = "system-ui, sans-serif",
            fontSize = "13px"
          )
        ),
        rowStyle = rowStyle_fn,
        bordered = FALSE,
        striped = FALSE,
        highlight = TRUE,
        style = list(
          fontFamily = "system-ui, sans-serif",
          fontSize = "13px",
          borderCollapse = "collapse",
          borderSpacing = "0",
          margin = "0 auto",
          width = "auto"
        )
      )
    )),
    style = "max-width: 100%; overflow-x: auto;"
  )
}

# Replaces median with custom function to take lower of two middle values in even-numbered lists
median_floor <- function(x) {
  x <- sort(x[!is.na(x)])
  n <- length(x)
  if (n == 0) return(NA)
  if (n %% 2 == 1) {
    x[(n + 1) / 2]
  } else {
    x[n / 2]  # lower of the two middles
  }
}



render_t2_table <- function(df, 
                            aoc_id = params$AOC, 
                            reference_sites = params$reference_sites, 
                            length_levels = NULL, 
                            interest_species = params$interest_species, 
                            exclude_t1_passed = TRUE,
                            table_height = "1500px") {
  

  
  if (is.null(length_levels)) {
    length_levels <- tryCatch(get("length_levels", envir = .GlobalEnv),
                              error = function(...) intersect(names(df), names(df)))
  }
  

  
  aoc_combinations <- prep_aoc_combinations(df, aoc_id, length_levels)
  
  filtered_data <- df %>%
    filter_advisory_data(site_ids = c(reference_sites, aoc_id), aoc_id, length_levels) %>%
    semi_join(aoc_combinations, by = c("Species", "Size", "Population")) %>%
    filter_interest_species(interest_species)
  
  if (nrow(filtered_data) == 0) {
    warning("Filtered data is empty. Check AOC and reference site IDs or species filter.")
    return(reactable(data.frame(Message = "No advisory data available for selected filters.")))
  }
  
  base_data <- summarise_max_advisory(filtered_data)
  
  if (exclude_t1_passed) {
    flags <- get_species_pass_flags(cons_data, aoc_id, reference_sites, length_levels)
    passed_species <- flags %>% filter(t1_pass) %>% pull(Species)
    filtered_data <- filtered_data %>% filter(!Species %in% passed_species)
    base_data <- base_data %>% filter(!Species %in% passed_species)
  }
  
  
  
  aoc_data <- base_data %>%
    filter(site_type == "AOC") %>%
    pivot_wider(names_from = Size, values_from = advisory) %>%
    mutate(site_order = 1)
  
  ref_long <- base_data %>% filter(site_type == "Reference")
  
  ref_medians_raw <- ref_long %>%
    group_by(Species, Population, Size) %>%
    summarise(Median = median_floor(advisory), .groups = "drop") %>%
    pivot_wider(names_from = Size, values_from = Median)
  size_cols_medians <- intersect(length_levels, names(ref_medians_raw))
  ref_medians <- ref_medians_raw %>%
    mutate(Site = "Reference Median", site_type = "Reference", site_order = 2) %>%
    select(Species, Population, all_of(size_cols_medians), Site, site_type, site_order)
  
  ref_n_raw <- ref_long %>%
    group_by(Species, Population, Size) %>%
    summarise(n = n(), .groups = "drop") %>%
    pivot_wider(names_from = Size, values_from = n)
  size_cols_n <- intersect(length_levels, names(ref_n_raw))
  ref_n <- ref_n_raw %>%
    mutate(Site = "n", site_type = "Reference", site_order = 3) %>%
    select(Species, Population, all_of(size_cols_n), Site, site_type, site_order)
  
  ref_data <- ref_long %>%
    pivot_wider(names_from = Size, values_from = advisory)
  
  aoc_median_combo <- bind_rows(aoc_data, ref_medians, ref_n)
  display_data <- add_row_order_labels(aoc_median_combo, length_levels)
  size_cols_display <- intersect(length_levels, names(display_data))
  
  if (length(size_cols_display) == 0 || nrow(ref_medians) == 0) {
    warning("No reference medians or size columns found. Check site IDs, species, or data coverage.")
    return(reactable(data.frame(Message = "No reference data available for selected filters.")))
  }
  
  comparison_lookup <- ref_medians %>%
    select(Species, Population, all_of(size_cols_medians)) %>%
    pivot_longer(cols = all_of(size_cols_medians), names_to = "Size", values_to = "Median") %>%
    mutate(id = paste(Species, Population, Size, sep = "||"))
  
  n_lookup <- ref_n %>%
    select(Species, Population, all_of(size_cols_n)) %>%
    pivot_longer(cols = all_of(size_cols_n), names_to = "Size", values_to = "n") %>%
    mutate(id = paste(Species, Population, Size, sep = "||"))
  
  comparison_medians <- setNames(as.list(comparison_lookup$Median), comparison_lookup$id)
  sample_ns <- setNames(as.list(n_lookup$n), n_lookup$id)
  
  columns_list <- make_common_column_defs()
  rowStyle_fn <- function(index) {
    row <- display_data[index, ]
    prev_row <- if (index > 1) display_data[index - 1, ] else NULL
    next_row <- if (index < nrow(display_data)) display_data[index + 1, ] else NULL
    
    style <- list()
    if (row$Site == "Reference Median") style$fontWeight <- "bold"
    if (is.null(prev_row) || prev_row$Species != row$Species) style$borderTop <- "2px solid #666"
    if (is.null(next_row) || next_row$Species != row$Species) style$borderBottom <- "2px solid #666"
    return(style)
  }
  
  for (col in size_cols_display) {
    columns_list[[col]] <- colDef(
      name = col,
      align = "center",
      sortable = FALSE,
      style = JS(sprintf(
        "function(rowInfo, colInfo, state) {
          const row = rowInfo.row;
          const val = row[colInfo.id];
          const id = row.Species + '||' + row.Population + '||' + '%s';
          const ref = state.meta.medians[id];
          const n = state.meta.ns[id];

          if (row.Site === 'n') { return { fontSize: '11px', color: '#666', fontStyle: 'italic', fontFamily: 'system-ui, sans-serif' }; }
          if (row.site_type === 'AOC') {
            if (val === null) { return { background: '#eeeeee', color: '#000000', fontWeight: 'bold', fontSize: '15px', fontFamily: 'system-ui, sans-serif' }; }
            if (n === undefined || n < 3 || ref === undefined || ref === null) {
              return { background: '#999999', color: '#ffffff', fontWeight: 'bold', fontSize: '15px', fontFamily: 'system-ui, sans-serif' }; }
            if (val < ref) {
              return { background: '#d80032', color: '#ffffff', fontWeight: 'bold', fontSize: '15px', fontFamily: 'system-ui, sans-serif' }; }
            return { background: '#4CAF50', color: '#ffffff', fontWeight: 'bold', fontSize: '15px', fontFamily: 'system-ui, sans-serif' }; }
          return { fontWeight: 'normal', fontSize: '13px', fontFamily: 'system-ui, sans-serif' }; }",
        col))
    )
  }
  
  return(
    reactable(
      display_data,
      columns = columns_list,
      defaultExpanded = FALSE,
      bordered = FALSE,
      striped = FALSE,
      highlight = TRUE,
      pagination = FALSE,
      sortable = FALSE,
      height = table_height,
      rowStyle = rowStyle_fn,
      style = list(
        fontFamily = "system-ui, sans-serif",
        fontSize = "13px",
        borderCollapse = "collapse",
        borderSpacing = "0",
        margin = "0 auto",
        width = "auto"
      ),
      details = function(index) {
        row <- display_data[index, ]
        if (row$Site == "Reference Median") {
          ref_rows <- ref_data %>%
            filter(Species == row$Species, Population == row$Population)
          ref_cols_present <- intersect(size_cols_display, names(ref_rows))
          ref_rows <- ref_rows %>%
            select(Site, all_of(ref_cols_present))
          reactable(ref_rows, compact = TRUE, bordered = TRUE, pagination = FALSE)
        } else {
          NULL
        }
      },
      meta = list(medians = comparison_medians, ns = sample_ns)
    )
  )
}

#' Generate a waterbody selector input (Shiny-only)
#'
#' @param choices A character vector of waterbody names
#' @return A Shiny UI selectizeInput or an informative error if Shiny is not available
make_waterbody_selector <- function(choices) {
  if (!requireNamespace("shiny", quietly = TRUE)) {
    stop("Shiny is not installed. This input is only available in a Shiny app context.")
  }
  
  shiny::selectizeInput(
    inputId = "waterbody",
    label = "Select a waterbody",
    choices = choices,
    multiple = FALSE,
    options = list(
      placeholder = "Start typing a waterbody name...",
      maxOptions = 15
    )
  )
}

